# qr_code_scanner.py
# A simple QR code scanner for Raspberry Pi using picamera2 on a CSI camera.

import time
import logging
from picamera2 import Picamera2
from pyzbar.pyzbar import decode

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def initialize_camera():
    """Initializes the CSI camera module."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        logging.info("CSI camera initialized successfully.")
        return camera
    except Exception as e:
        logging.error(f"Failed to initialize CSI camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the CSI camera."""
    try:
        frame = camera.capture_array()
        logging.info("Frame captured successfully.")
        return frame
    except Exception as e:
        logging.error(f"Failed to capture frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in the given frame using pyzbar."""
    try:
        decoded_objects = decode(frame)
        if decoded_objects:
            logging.info(f"QR code detected: {decoded_objects[0].data.decode('utf-8')}")
            return True
        else:
            logging.info("No QR code detected.")
            return False
    except Exception as e:
        logging.error(f"Failed to decode QR code: {e}")
        return False

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        frame = capture_frame(camera)
        if frame is not None:
            if decode_qr_code(frame):
                print('Hello, World!')
            else:
                print('No QR code detected.')
    except KeyboardInterrupt:
        logging.info("Script interrupted by user.")
    finally:
        # Ensure camera resources are released
        if camera:
            camera.stop()
            camera.close()
            logging.info("CSI camera resources released.")

if __name__ == "__main__":
    main()

