#!/usr/bin/env python3

import time
import datetime
import logging
import json
import os
import signal
import sys
from gpiozero import DistanceSensor

# Configuration file path
CONFIG_FILE = "config.json"

# Default configuration values
DEFAULT_CONFIG = {
    "sensors": [
        {
            "trigger_pin": 17,
            "echo_pin": 18,
            "offset": 0.0,
            "max_distance": 200.0
        },
        {
            "trigger_pin": 22,
            "echo_pin": 23,
            "offset": 0.0,
            "max_distance": 200.0
        },
        {
            "trigger_pin": 24,
            "echo_pin": 25,
            "offset": 0.0,
            "max_distance": 200.0
        }
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# Global variables
running = True
last_alert_times = {}

# Configure logging
logging.basicConfig(filename=DEFAULT_CONFIG["log_file"], level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Received shutdown signal. Exiting...")
    running = False
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to load configuration from file
def load_config():
    global DEFAULT_CONFIG
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
            # Validate config structure
            if not isinstance(config, dict) or "sensors" not in config or not isinstance(config["sensors"], list):
                raise ValueError("Invalid config file format. Must be a dictionary with 'sensors' as a list.")
            for sensor in config["sensors"]:
                if not isinstance(sensor, dict) or "trigger_pin" not in sensor or "echo_pin" not in sensor or "offset" not in sensor or "max_distance" not in sensor:
                    raise ValueError("Invalid sensor configuration. Must be a dictionary with 'trigger_pin', 'echo_pin', 'offset', and 'max_distance' keys.")
                if not isinstance(sensor["trigger_pin"], int) or not isinstance(sensor["echo_pin"], int) or not isinstance(sensor["offset"], (int, float)) or not isinstance(sensor["max_distance"], (int, float)):
                    raise ValueError("Sensor pin and offset must be integers or floats.")
                if not 0 <= sensor["trigger_pin"] <= 27 or not 0 <= sensor["echo_pin"] <= 27:
                    raise ValueError("Sensor pin numbers must be between 0 and 27.")
                if not 0 <= sensor["offset"] <= 100:
                    raise ValueError("Sensor offset must be between 0 and 100.")
                if not 10 <= sensor["max_distance"] <= 200:
                    raise ValueError("Sensor max_distance must be between 10 and 200.")
            # Validate alert thresholds
            if not isinstance(config["alert_threshold_low"], (int, float)) or not isinstance(config["alert_threshold_high"], (int, float)):
                raise ValueError("Alert thresholds must be integers or floats.")
            if not 0 <= config["alert_threshold_low"] <= 200 or not 0 <= config["alert_threshold_high"] <= 200:
                raise ValueError("Alert thresholds must be between 0 and 200.")
            # Validate alert repeat delay
            if not isinstance(config["alert_repeat_delay"], int):
                raise ValueError("Alert repeat delay must be an integer.")
            if config["alert_repeat_delay"] <= 0:
                raise ValueError("Alert repeat delay must be a positive integer.")
            # Validate log file path
            if not isinstance(config["log_file"], str):
                raise ValueError("Log file path must be a string.")
            DEFAULT_CONFIG = config
            logging.info("Configuration loaded from file.")
    except FileNotFoundError:
        logging.warning("Configuration file not found. Using default configuration.")
    except json.JSONDecodeError:
        logging.error("Error decoding JSON from configuration file. Using default configuration.")
    except ValueError as e:
        logging.error(f"Invalid configuration: {e}. Using default configuration.")

# Function to initialize GPIO pins
def initialize_gpio(sensors):
    try:
        for sensor in sensors:
            # Initialize DistanceSensor objects with timeout of 50ms
            sensor["sensor"] = DistanceSensor(echo=sensor["echo_pin"], trigger=sensor["trigger_pin"], timeout=0.005)
            logging.info(f"Sensor {sensor['trigger_pin']}/{sensor['echo_pin']} initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO pins: {e}")
        return False
    return True

# Function to measure distance from an ultrasonic sensor
def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        # Measure distance using the DistanceSensor object
        distance = sensor["sensor"].distance * 100  # Convert to cm
        # Apply offset
        distance += offset
        # Clamp distance to the valid range
        distance = max(0, min(distance, max_distance))
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance from sensor {trigger_pin}/{echo_pin}: {e}")
        return None

# Function to calculate water level from distance
def calculate_water_level(distance, max_distance):
    water_level = max_distance - distance
    return water_level

# Function to log measurements
def log_measurement(trigger_pin, echo_pin, distance, water_level):
    timestamp = datetime.datetime.now().isoformat()
    log_message = f"Sensor {trigger_pin}/{echo_pin}: Distance={distance:.2f} cm, Water Level={water_level:.2f} cm"
    logging.info(log_message)

# Function to log alerts
def log_alert(sensor_id, alert_type, water_level):
    timestamp = datetime.datetime.now().isoformat()
    log_message = f"Alert: Sensor {sensor_id} - {alert_type} - Water Level: {water_level:.2f} cm"
    logging.warning(log_message)

# Function to check for alerts
def check_alerts(sensor_id, water_level, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    global last_alert_times
    alert_type = "Low Water Level" if water_level < alert_threshold_low else "High Water Level"
    now = time.time()
    if alert_type in last_alert_times and (now - last_alert_times[alert_type]) < alert_repeat_delay:
        return False  # Suppress repeated alerts
    last_alert_times[alert_type] = now
    return True

# Main function
def main():
    global running, DEFAULT_CONFIG

    # Load configuration
    load_config()

    # Initialize GPIO pins
    sensors = DEFAULT_CONFIG["sensors"]
    if not initialize_gpio(sensors):
        logging.error("Failed to initialize GPIO pins. Exiting.")
        sys.exit(1)

    # Main loop
    try:
        while running:
            valid_readings = []
            for sensor in sensors:
                # Measure distance
                distance = measure_distance(sensor["trigger_pin"], sensor["echo_pin"], sensor["offset"], sensor["max_distance"])
                if distance is not None:
                    valid_readings.append(distance)
                else:
                    logging.warning(f"Skipping sensor {sensor['trigger_pin']}/{sensor['echo_pin']} due to measurement failure.")

            if valid_readings:
                # Calculate water level
                water_level = calculate_water_level(sum(valid_readings) / len(valid_readings), DEFAULT_CONFIG["max_distance"])
                # Log measurement
                log_measurement(sensor["trigger_pin"], sensor["echo_pin"], sum(valid_readings) / len(valid_readings), water_level)

                # Check for alerts
                if check_alerts(sensor["trigger_pin"], water_level, DEFAULT_CONFIG["alert_threshold_low"], DEFAULT_CONFIG["alert_threshold_high"], DEFAULT_CONFIG["alert_repeat_delay"]):
                    log_alert(sensor["trigger_pin"], "Low Water Level", water_level)
            else:
                logging.warning("No valid readings from any sensor. Skipping alert check.")

            # Wait before next measurement
            time.sleep(5)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Cleanup GPIO pins
        for sensor in sensors:
            if "sensor" in sensor and sensor["sensor"]:
                sensor["sensor"].close()
        logging.info("GPIO cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

