# bluetooth_transmitter_rpi.py
# A simple Bluetooth transmitter for Raspberry Pi using pyserial

import serial
import time
import contextlib
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the Bluetooth port and baud rate
BLUETOOTH_PORT = '/dev/rfcomm4'
BLUETOOTH_BAUDRATE = 38400

@contextlib.contextmanager
def bluetooth_serial_connection(port, baudrate):
    """Context manager for Bluetooth serial port connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        logging.info(f"Connected to Bluetooth port {port} at {baudrate} baud.")
        yield ser
    except serial.SerialException as e:
        logging.error(f"Error opening Bluetooth port: {e}")
        raise
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()
            logging.info("Bluetooth port closed.")

def transmit_data(serial_connection, data):
    """Transmits data over the Bluetooth serial port."""
    try:
        encoded_data = data.encode('utf-8')
        serial_connection.write(b'X' + encoded_data)
        logging.info(f"Transmitted: {data}")
        return len(encoded_data)
    except serial.SerialException as e:
        logging.error(f"Error writing to Bluetooth port: {e}")
        return 0

def main():
    """Main function to handle user input and transmit data."""
    try:
        with bluetooth_serial_connection(BLUETOOTH_PORT, BLUETOOTH_BAUDRATE) as ser:
            while True:
                user_input = input("Enter data to transmit (or 'q' to quit): ")
                if user_input.lower() == 'q':
                    break
                bytes_sent = transmit_data(ser, user_input)
                if bytes_sent > 0:
                    logging.info(f"Sent {bytes_sent} bytes.")
                else:
                    logging.warning("No data sent.")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

