        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature = float(line.split(':')[1].strip('C'))
            return temperature
        return None
    except ValueError:
        print("Error: Invalid data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading data: {e}")
        return None

def display_temperature(temperature):
    """Displays the temperature in Celsius."""
    if temperature is not None:
        print(f'Temperature: {temperature:.1f} C')

def main():
    """Main function to read and display temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature = read_temperature_data(serial_connection)
            display_temperature(temperature)
            time.sleep(0.5)  # Wait 0.5 seconds before the next reading

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")

    finally:
        # Ensure the serial port is closed on exit
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

