    """Renders the main control page."""
    return render_template('index.html')

# Route to turn the LED on
@app.route('/light_on')
def light_on():
    """Turns the LED on."""
    try:
        led.on()  # Activate the LED
        return render_template('status.html', message='LED is ON')
    except Exception as e:
        print(f"Error turning LED on: {e}")
        return render_template('status.html', message=f'Error: {e}')

# Route to turn the LED off
