#!/usr/bin/env python3

"""
This module provides a robust and optimized interface for controlling a servo motor
via a Modbus RTU servo controller connected to a Raspberry Pi. It incorporates
detailed error handling, performance optimizations, and adheres to best
practices for hardware interaction.
"""

import time
import logging
from typing import Dict, Any, Union, Tuple

import serial
from pymodbus.client import ModbusSerialClient
from pymodbus.constants import Endian
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.exceptions import ModbusIOException, ModbusCRCError, ModbusException

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for Modbus function codes
FC_READ_ HoldING_REGISTERS = 3
FC_WRITE_SINGLE_REGISTER = 6
FC_WRITE_MULTIPLE_REGISTERS = 16

# Register addresses (using descriptive names)
CONTROL = 0x3100
STATUS = 0x3000
OPMODE = 0x3500
POSITION_FEEDBACK = 0x3700
VELOCITY_FEEDBACK = 0x3B00
POSITION_COMMAND = 0x4000
VELOCITY_COMMAND = 0x6F00

# Modbus register map
REGISTER_MAP: Dict[str, Dict[str, Any]] = {
    "CONTROL": {"R/W": "W", "Register": CONTROL, "functioncode": FC_WRITE_SINGLE_REGISTER, "Value": {"Stop": 0x0006, "Start": 0x000F}},
    "STATUS": {"R/W": "R", "Register": STATUS, "functioncode": FC_READ_ HoldING_REGISTERS, "read_length": 2},
    "OPMODE": {"R/W": "W", "Register": OPMODE, "functioncode": FC_WRITE_SINGLE_REGISTER, "Value": {"Position": 1}},  # Example value for Position mode
    "VelocityFeedback": {"R/W": "R", "Register": VELOCITY_FEEDBACK, "functioncode": FC_READ_ HoldING_REGISTERS, "read_length": 2},
    "PositionFeedback": {"R/W": "R", "Register": POSITION_FEEDBACK, "functioncode": FC_READ_ HoldING_REGISTERS, "read_length": 2},
    "VelocityCommand": {"R/W": "W", "Register": VELOCITY_COMMAND, "functioncode": FC_WRITE_SINGLE_REGISTER},
    "PositionCommand": {"R/W": "W", "Register": POSITION_COMMAND, "functioncode": FC_WRITE_SINGLE_REGISTER},
}


class ServoError(Exception):
    """Custom exception for Servo-related errors."""
    pass


class Servo:
    """
    A class to encapsulate the communication and control of a servo motor via a Modbus RTU servo controller.
    """

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 0.5):
        """
        Initializes the Servo object.

        Args:
            port (str): The serial port to connect to (default: "/dev/serial0").
            baudrate (int): The baud rate for serial communication (default: 115200).
            timeout (float): Timeout for Modbus communication in seconds (default: 0.5).
        """
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client = None  # Initialize client to None
        self.connect()

    def connect(self) -> None:
        """
        Establishes a connection to the Modbus RTU servo controller.

        Raises:
            ServoError: If connection fails.
        """
        try:
            self.client = ModbusSerialClient(method='rtu', port=self.port, baudrate=self.baudrate, parity='N', stopbits=1, bytesize=8, timeout=self.timeout)
            if not self.client.connect():
                raise ServoError(f"Failed to connect to Modbus device on {self.port}")
            logger.info(f"Connected to Modbus device on {self.port}")
        except serial.SerialException as e:
            raise ServoError(f"Serial communication error: {e}") from e
        except Exception as e:
            raise ServoError(f"Unexpected connection error: {e}") from e

    def close(self) -> None:
        """
        Closes the connection to the Modbus RTU servo controller.
        """
        if self.client:
            try:
                self.client.close()
                logger.info("Connection to Modbus device closed.")
            except Exception as e:
                logger.error(f"Error closing connection: {e}")
            finally:
                self.client = None

    def _read_register(self, register_name: str, data_type: str = "uint16", count: int = 1) -> Union[int, float, None]:
        """
        Reads a value from a Modbus register.

        Args:
            register_name (str): The name of the register (e.g., "CONTROL", "STATUS").
            data_type (str): The data type of the register ("uint16" or "float").
            count (int): The number of registers to read (default: 1).

        Returns:
            Union[int, float, None]: The register value, or None if an error occurred.
        """
        try:
            register_info = REGISTER_MAP.get(register_name)
            if not register_info:
                raise ServoError(f"Invalid register name: {register_name}")

            if register_info["R/W"] != "R":
                raise ServoError(f"Register {register_name} is not readable.")

            if data_type == "uint16":
                result = self.client.read_holding_registers(register_info["Register"], count, unit=1)
                if result.isError():
                    raise ModbusException(f"Modbus error reading register {register_name}: {result}")
                decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.Big, wordorder=Endian.Little)
                return decoder.decode_16bit_uint()
            elif data_type == "float":
                result = self.client.read_holding_registers(register_info["Register"], count, unit=1)
                if result.isError():
                    raise ModbusException(f"Modbus error reading register {register_name}: {result}")
                decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.Big, wordorder=Endian.Little)
                return decoder.decode_32bit_float()
            else:
                raise ServoError(f"Invalid data type: {data_type}")

        except ModbusIOException as e:
            raise ServoError(f"Modbus IO error: {e}") from e
        except ModbusCRCError as e:
            raise ServoError(f"Modbus CRC error: {e}") from e
        except Exception as e:
            raise ServoError(f"Unexpected error reading register {register_name}: {e}") from e

    def _write_register(self, register_name: str, value: Union[int, float]) -> None:
        """
        Writes a value to a Modbus register.

        Args:
            register_name (str): The name of the register (e.g., "CONTROL", "STATUS").
            value: The value to write.
        """
        try:
            register_info = REGISTER_MAP.get(register_name)
            if not register_info:
                raise ServoError(f"Invalid register name: {register_name}")

            if register_info["R/W"] != "W":
                raise ServoError(f"Register {register_name} is not writable.")

            if isinstance(value, int):
                data_type = "uint16"
                count = 1
                data = [value]
            elif isinstance(value, float):
                data_type = "float"
                count = 1
                data = [int(value * 65536)]  # Convert to 16-bit integer
            else:
                raise ServoError(f"Invalid value type: {type(value)}")

            if data_type == "uint16":
                result = self.client.write_holding_registers(register_info["Register"], data, unit=1)
                if result.isError():
                    raise ModbusException(f"Modbus error writing to register {register_name}: {result}")
            elif data_type == "float":
                result = self.client.write_holding_registers(register_info["Register"], data, unit=1)
                if result.isError():
                    raise ModbusException(f"Modbus error writing to register {register_name}: {result}")
            else:
                raise ServoError(f"Invalid data type: {data_type}")

        except ModbusIOException as e:
            raise ServoError(f"Modbus IO error: {e}") from e
        except ModbusCRCError as e:
            raise ServoError(f"Modbus CRC error: {e}") from e
        except Exception as e:
            raise ServoError(f"Unexpected error writing to register {register_name}: {e}") from e

    def get_status(self) -> Dict[str, Any]:
        """
        Gets the current status of the servo motor.

        Returns:
            Dict[str, Any]: A dictionary containing the status information.
        """
        try:
            return self._read_register_group("STATUS")
        except ServoError as e:
            logger.error(f"Error getting status: {e}")
            return {}

    def set_velocity_command(self, velocity: float) -> None:
        """
        Sets the velocity command for the servo motor.

        Args:
            velocity (float): The desired velocity in degrees per second.
        """
        try:
            self._write_register("VELOCITY_COMMAND", velocity)
        except ServoError as e:
            logger.error(f"Error setting velocity command: {e}")

    def set_position_command(self, position: float) -> None:
        """
        Sets the position command for the servo motor.

        Args:
            position (float): The desired position in degrees.
        """
        try:
            self._write_register("POSITION_COMMAND", position)
        except ServoError as e:
            logger.error(f"Error setting position command: {e}")

    def set_opmode(self, mode: str) -> None:
        """
        Sets the operating mode of the servo motor.

        Args:
            mode (str): The desired operating mode ("Position", "Velocity", etc.).
        """
        try:
            value = REGISTER_MAP["OPMODE"]["Value"].get(mode)
            if value is None:
                raise ValueError(f"Invalid operating mode: {mode}")
            self._write_register("OPMODE", value)
        except ValueError as e:
            logger.error(f"Invalid operating mode: {e}")
        except ServoError as e:
            logger.error(f"Error setting operating mode: {e}")

    def _read_register_group(self, register_name: str, count: int = 1) -> Dict[str, Any]:
        """
        Reads a group of registers and returns the values as a dictionary.

        Args:
            register_name (str): The name of the first register in the group.
            count (int): The number of registers to read.

        Returns:
            Dict[str, Any]: A dictionary containing the register values.
        """
        try:
            register_info = REGISTER_MAP.get(register_name)
            if not register_info:
                raise ServoError(f"Invalid register name: {register_name}")

            result = self.client.read_holding_registers(register_info["Register"], count, unit=1)
            if result.isError():
                raise ModbusException(f"Modbus error reading register group {register_name}: {result}")

            decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.Big, wordorder=Endian.Little)
            values = {}
            for i in range(count):
                register_name = f"{register_name}{i+1}"
                register_info = REGISTER_MAP.get(register_name)
                if register_info and register_info["R/W"] == "R":
                    if register_info["functioncode"] == FC_READ_HOLDING_REGISTERS:
                        if register_info["read_length"] == 2:
                            values[register_name] = decoder.decode_16bit_uint()
                        elif register_info["read_length"] == 4:
                            values[register_name] = decoder.decode_32bit_float()
                        else:
                            raise ServoError(f"Invalid read_length for register {register_name}: {register_info['read_length']}")
                    else:
                        raise ServoError(f"Unsupported Modbus function code for register {register_name}: {register_info['functioncode']}")
            return values
        except ModbusIOException as e:
            raise ServoError(f"Modbus IO error: {e}") from e
        except ModbusCRCError as e:
            raise ServoError(f"Modbus CRC error: {e}") from e
        except Exception as e:
            raise ServoError(f"Unexpected error reading register group {register_name}: {e}") from e

    def get_velocity_feedback(self) -> float:
        """
        Gets the current velocity of the servo motor.

        Returns:
            float: The current velocity in degrees per second.
        """
        try:
            return self._read_register("VELOCITY_FEEDBACK", data_type="float")
        except ServoError as e:
            logger.error(f"Error getting velocity feedback: {e}")
            return 0.0

    def get_position_feedback(self) -> float:
        """
        Gets the current position of the servo motor.

        Returns:
            float: The current position in degrees.
        """
        try:
            return self._read_register("POSITION_FEEDBACK", data_type="float")
        except ServoError as e:
            logger.error(f"Error getting position feedback: {e}")
            return 0.0


def main():
    """
    Main function to demonstrate servo control.
    """
    try:
        servo = Servo()
        servo.set_opmode("Position")
        servo.set_velocity_command(100)
        servo.set_position_command(180)
        time.sleep(2)
        servo.set_velocity_command(0)
        logger.info("Servo control sequence completed.")
    except ServoError as e:
        logger.error(f"Servo error: {e}")
    finally:
        if 'servo' in locals():
            servo.close()


if __name__ == "__main__":
    main()

