import time
import board
import busio
import adafruit_servokit

# Constants for servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4
METAL = 135
PLASTIC = 180
PAPER = 90

# Servo settings
SERVO_MIN_PULSE = 500
SERVO_MAX_PULSE = 2500
DEFAULT_SERVO_ANGLE = 90
SERVO_STEP_SIZE = 5
SERVO_DELAY = 0.04

# Initialize I2C bus
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except ValueError as e:
    print(f"Error initializing I2C: {e}")
    exit()

# Initialize ServoKit
try:
    kit = adafruit_servokit.ServoKit(channels=16)
except ValueError as e:
    print(f"Error initializing ServoKit: {e}")
    exit()


def move_servo(channel, target_angle, step_size=SERVO_STEP_SIZE, delay=SERVO_DELAY):
    """Moves a servo smoothly to a target angle."""
    if not 0 <= channel <= 15:
        raise ValueError("Invalid servo channel. Must be between 0 and 15.")
    if not 0 <= target_angle <= 180:
        raise ValueError("Invalid target angle. Must be between 0 and 180.")

    current_angle = kit.servo[channel].angle or DEFAULT_SERVO_ANGLE  # Get current angle or default

    if target_angle > current_angle:
        angle_range = range(int(current_angle), int(target_angle) + 1, step_size)
    else:
        angle_range = range(int(current_angle), int(target_angle) - 1, -step_size)

    for angle in angle_range:
        kit.servo[channel].angle = angle
        time.sleep(delay)


def seek(angle):
    """Seeks to a specific angle."""
    move_servo(SEEK, angle)


def deseek(angle):
    """Deseeks to a specific angle."""
    move_servo(SEEK, angle)


def drop(angle):
    """Drops an object."""
    move_servo(DROP, angle)


def pick(angle):
    """Picks up an object."""
    move_servo(DROP, angle)


def grab(angle):
    """Grabs an object."""
    move_servo(GRAB, angle)


def release(angle):
    """Releases an object."""
    move_servo(GRAB, angle)


def collect_object_steps(seek_angle):
    """Performs the steps for collecting an object."""
    seek(seek_angle)
    grab(90)
    drop(160)
    raise NotImplementedError("collect_object_steps not implemented")


def drop_object_steps(drop_angle):
    """Performs the steps for dropping an object."""
    drop(drop_angle)
    release(120)
    raise NotImplementedError("drop_object_steps not implemented")


def get_pos_x(x_center):
    """Calculates the x-coordinate from the center of the object."""
    if x_center < 160:
        return 0
    elif x_center < 240:
        return 45
    elif x_center < 320:
        return 90
    else:
        return DEFAULT_SERVO_ANGLE


def get_pos_y(y_center):
    """Calculates the y-coordinate from the center of the object."""
    if y_center < 120:
        return 0
    elif y_center < 160:
        return 45
    elif y_center < 200:
        return 90
    else:
        return DEFAULT_SERVO_ANGLE


def collect_object(x_center, y_center, drop_angle):
    """Collects an object at a specific location and drops it."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)

    try:
        collect_object_steps(pos_x)
        move_servo(BASE, pos_y)
        drop_object_steps(drop_angle)
        move_servo(BASE, DEFAULT_SERVO_ANGLE)
    except Exception as e:
        print(f"Error during object collection: {e}")
        raise  # Re-raise the exception to be handled by the caller


def main():
    """Main function to run the object collection."""
    try:
        while True:
            # Example usage:
            collect_object(160, 160, 100)  # Collect object at (160, 160), dropping at 100 degrees
            time.sleep(2)

    except KeyboardInterrupt:
        print("Program stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure servos are stopped and I2C bus is released
        for channel in range(16):
            kit.servo[channel].angle = None
        i2c.deinit()
        print("Servos stopped and I2C bus released.")


if __name__ == "__main__":
    main()

