#!/usr/bin/env python3

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and optimized driver for the DS1338 RTC chip,
using the smbus2 library for I2C communication. It includes comprehensive
error handling, detailed documentation, and best practices for hardware interaction.
"""

import smbus2
import time
import datetime
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_I2C_BUS = 1
DEFAULT_I2C_ADDRESS = 0x68
DEFAULT_CENTURY = 21

# Register Addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
REG_STATUS = 0x0F

# Control Register Bits
CTRL_OSCILLATE = 0x80
CTRL_UPDATE = 0x01
CTRL_SQWE = 0x40
CTRL_OUT = 0x20
CTRL_INT = 0x08

# Status Register Bits
STATUS_OSCILLATE = 0x80
STATUS_UPDATE = 0x01
STATUS_SQWE = 0x40
STATUS_OUT = 0x20
STATUS_INT = 0x08

class DS1338:
    """
    A class to interface with the DS1338 RTC chip using the smbus2 library.
    """

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, i2c_address=DEFAULT_I2C_ADDRESS, century=DEFAULT_CENTURY):
        """
        Initializes the DS1338 object.

        Args:
            i2c_bus (int): The I2C bus number.
            i2c_address (int): The I2C address of the DS1338.
            century (int): The century for the year (e.g., 21 for 21xx).
        """
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.century = century
        self.bus = None  # Initialize bus to None
        self.running = True  # Flag to control the main loop

        # Validate I2C bus and address
        if not isinstance(self.i2c_bus, int) or not isinstance(self.i2c_address, int):
            raise ValueError("I2C bus and address must be integers.")

        # Initialize signal handler for graceful shutdown
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, sig, frame):
        """Handles SIGINT and SIGTERM signals for graceful shutdown."""
        logger.info("Received shutdown signal. Exiting gracefully...")
        self.running = False

    def _validate_register(self, register):
        """Validates that the register address is within the expected range."""
        if not isinstance(register, int):
            raise TypeError("Register must be an integer.")
        if not 0x00 <= register <= 0x7F:
            raise ValueError(f"Register address {register:02X} is out of range (0x00-0x7F).")

    def _validate_value(self, value, min_val=None, max_val=None):
        """Validates that the value is within the expected range."""
        if not isinstance(value, int):
            raise TypeError("Value must be an integer.")
        if min_val is not None and value < min_val:
            raise ValueError(f"Value {value} is below minimum allowed value {min_val}.")
        if max_val is not None and value > max_val:
            raise ValueError(f"Value {value} is above maximum allowed value {max_val}.")

    def _bcd_to_int(self, bcd):
        """Converts Binary Coded Decimal (BCD) to integer."""
        try:
            return (bcd >> 4) * 10 + (bcd & 0x0F)
        except TypeError:
            raise TypeError("BCD value must be an integer.")

    def _int_to_bcd(self, integer):
        """Converts integer to Binary Coded Decimal (BCD)."""
        try:
            return (integer // 10 << 4) | (integer % 10)
        except TypeError:
            raise TypeError("Integer value must be an integer.")

    def _read_register(self, register):
        """Reads a byte from the specified register."""
        self._validate_register(register)
        try:
            return self.bus.read_byte_data(self.i2c_address, register)
        except (IOError, OSError) as e:
            logger.error(f"I2C read error at register 0x{register:02X}: {e}")
            return None

    def _write_register(self, register, value):
        """Writes a byte to the specified register."""
        self._validate_register(register)
        self._validate_value(value)
        try:
            self.bus.write_byte_data(self.i2c_address, register, value)
        except (IOError, OSError) as e:
            logger.error(f"I2C write error at register 0x{register:02X}: {e}")

    def _read_all(self):
        """Reads all registers and returns them as a dictionary."""
        try:
            data = {}
            for register in range(0x00, 0x08):
                data[register] = self._read_register(register)
            return data
        except (IOError, OSError) as e:
            logger.error(f"I2C read error during all register read: {e}")
            return None

    def _write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """Writes all registers with the given values."""
        try:
            data = {}
            if seconds is not None:
                data[REG_SECONDS] = self._int_to_bcd(seconds)
            if minutes is not None:
                data[REG_MINUTES] = self._int_to_bcd(minutes)
            if hours is not None:
