This module provides a driver for the Maxim DS1338 RTC chip, using the I2C interface.
It allows for reading and writing date and time information to the RTC.
"""

import smbus2
import time
from datetime import datetime, timezone

class DS1338:
    """Driver for the Maxim DS1338 RTC."""

    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    def __init__(self, bus_number=1, device_address=0x68):
        """Initialize the DS1338 driver.

        Args:
            bus_number (int): The I2C bus number (default: 1).
            device_address (int): The I2C address of the DS1338 (default: 0x68).
        """
        self.bus_number = bus_number
        self.device_address = device_address
        self.bus = None  # Initialize bus to None

    def open(self):
        """Open the I2C bus."""
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            return True
        except FileNotFoundError:
            print(f"Error: I2C bus {self.bus_number} not found. Check your Raspberry Pi configuration.")
            return False
        except Exception as e:
            print(f"Error opening I2C bus: {e}")
            return False

    def close(self):
        """Close the I2C bus."""
        if self.bus:
            self.bus.close()
            self.bus = None

    def __enter__(self):
        """Context manager entry."""
        if not self.open():
            raise IOError("Failed to open I2C bus")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit."""
        self.close()

    def _read_register(self, register):
        """Read a byte from the specified register."""
        try:
            return self.bus.read_byte_data(self.device_address, register)
        except IOError as e:
            raise IOError(f"Error reading register 0x{register:02X}: {e}")

    def _write_register(self, register, value):
        """Write a byte to the specified register."""
        try:
            self.bus.write_byte_data(self.device_address, register, value)
        except IOError as e:
            raise IOError(f"Error writing to register 0x{register:02X}: {e}")

    def read_all(self):
        """Read all date and time registers and return them as a tuple."""
        try:
            seconds = self._read_register(self.REG_SECONDS) & 0x7F  # Clear CH bit
            minutes = self._read_register(self.REG_MINUTES)
            hours = self._read_register(self.REG_HOURS) & 0x3F  # Clear CH bit
            day = self._read_register(self.REG_DAY)
            date = self._read_register(self.REG_DATE)
            month = self._read_register(self.REG_MONTH)
            year = self._read_register(self.REG_YEAR)
            return (year, month, date, day, hours, minutes, seconds)
        except IOError as e:
            raise IOError(f"Error reading all registers: {e}")

    def read_datetime(self):
        """Read the current date and time and return it as a datetime object."""
        year, month, date, day, hours, minutes, seconds = self.read_all()
        year = 2000 + (year >> 4) * 10 + (year & 0x0F)  # Year is BCD, so shift and mask
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all date and time registers."""
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59")
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59")
        if not 0 <= hours <= 23:
            raise ValueError("Hours must be between 0 and 23")
        if not 1 <= day <= 7:
            raise ValueError("Day must be between 1 and 7")
        if not 1 <= date <= 31:
            raise ValueError("Date must be between 1 and 31")
        if not 1 <= month <= 12:
            raise ValueError("Month must be between 1 and 12")
        if not 2000 <= year <= 2099:
            raise ValueError("Year must be between 2000 and 2099")

        try:
            self._write_register(self.REG_SECONDS, seconds & 0x7F)  # Clear CH bit
            self._write_register(self.REG_MINUTES, minutes)
            self._write_register(self.REG_HOURS, hours | 0x40)  # Set CH bit for 24-hour mode
            self._write_register(self.REG_DAY, day)
            self._write_register(self.REG_DATE, date)
            self._write_register(self.REG_MONTH, month)
            self._write_register(self.REG_YEAR, year & 0x0F)  # Year is BCD, so mask the high bits
        except IOError as e:
            raise IOError(f"Error writing all registers: {e}")

    def write_datetime(self, dt):
        """Write a datetime object to the RTC."""
        self.write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        """Write the current system time to the RTC."""
        now = datetime.now(timezone.utc)
        self.write_datetime(now)


if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current time: {current_time}")
    except IOError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

