@app.route("/data", methods=["POST"])
def create_data_item():
    """
    Creates a new data item in the in-memory data store.
    """
    global data_store
    try:
        body = request.get_json()
        if not body:
            return Response("Invalid JSON payload.", status=400, mimetype="text/plain")

        name = body.get("name")
        done = body.get("done", False)

        if not name:
            return Response("Name is required.", status=400, mimetype="text/plain")

        if not isinstance(done, bool):
            return Response("Done must be a boolean.", status=400, mimetype="text/plain")

        with data_lock:
            new_item = {"id": max(data_store, key=lambda item: item["id"])["id"] + 1, "name": name, "done": done}
            data_store.append(new_item)
            return jsonify(new_item), 201, {"Location": f"/data/{new_item['id']}"}

    except Exception as e:
        logging.error(f"Error creating data item: {e}")
        return Response(f"Error: {e}", status=500, mimetype="text/plain")

