import json
import time
import threading
import logging
import signal
import sys

from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Flask application instance
app = Flask(__name__)

# Global data store
data_store = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": True}]

# Lock for thread-safe data access
data_lock = threading.Lock()

# Serial port configuration
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

# Serial port instance
serial_port = None

# Flag to control the main loop
running = True

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running, serial_port
    logging.info("Received signal, shutting down...")
    running = False
    if serial_port:
        try:
            serial_port.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")
    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

class SerialCommunicator:
    """
    A class to manage serial communication with the USB-serial instrument.
    """
    def __init__(self, port, baudrate, timeout):
        """
        Initializes the SerialCommunicator with the specified port, baud rate, and timeout.
        """
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None

    def open(self):
        """
        Opens the serial port.
        """
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial port {self.port} opened successfully.")
            return True
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port}: {e}")
            return False

    def send(self, command):
        """
        Sends a command to the serial port and reads the response.
        """
        if not self.serial_port:
            logging.error("Serial port not open.")
            return None

        try:
            self.serial_port.write(command.encode())
            response = self.receive_line()
            return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None

    def receive_line(self):
        """
        Reads a line from the serial port with a timeout.
        """
        if not self.serial_port:
            logging.error("Serial port not open.")
            return None

        try:
            line = self.serial_port.readline().decode().strip()
            return line
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None

    def close(self):
        """
        Closes the serial port.
        """
        if self.serial_port:
            try:
                self.serial_port.close()
                logging.info("Serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

# Initialize serial communicator
serial_communicator = SerialCommunicator(SERIAL_PORT, BAUD_RATE, TIMEOUT)

@app.route("/version", methods=["GET"])
def get_version():
    """
    Retrieves the version information from the USB-serial instrument.
    """
    global serial_communicator
    if not serial_communicator.open():
        return Response("Failed to open serial port.", status=500, mimetype="text/plain")

    try:
        response = serial_communicator.send("*IDN?\n")
        if response:
            return Response(response, mimetype="text/plain")
        else:
            return Response("Timeout waiting for response.", status=504, mimetype="text/plain")
    except Exception as e:
        logging.error(f"Error communicating with serial device: {e}")
        return Response(f"Error: {e}", status=502, mimetype="text/plain")
    finally:
        serial_communicator.close()

