# rfid_access_control_rpi.py
# A simple RFID access control system for Raspberry Pi using a USB reader.

import serial
import time
import datetime

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_rfid_tag(serial_connection):
    """Reads an RFID tag ID from the serial port."""
    try:
        tag_data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return tag_data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def log_access(log_file, tag_id):
    """Logs the access event to a file."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
        print(f'Access granted for RFID Tag: {tag_id}')
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to run the RFID access control system."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            tag_id = read_rfid_tag(serial_connection)

            if tag_id:
                log_access(LOG_FILE, tag_id)

            time.sleep(1)  # Check for new tag every second

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

