# pulse_oximeter_reader.py
# Reads heart rate and SpO2 from a pulse oximeter via UART on Raspberry Pi

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_pulse_oximeter_data(serial_connection):
    """Reads data from the pulse oximeter and returns heart rate and SpO2."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            heart_rate, spo2 = line.split(',')
            return heart_rate, spo2
        return None, None
    except ValueError:
        print("Invalid data received from pulse oximeter.")
        return None, None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    """Prints the heart rate and SpO2 readings."""
    if heart_rate is not None and spo2 is not None:
        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')

def main():
    """Main function to read and display pulse oximeter data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            heart_rate, spo2 = read_pulse_oximeter_data(serial_connection)
            display_pulse_oximeter_data(heart_rate, spo2)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

