from flask import Flask, Response, request, jsonify, abort
import json
import time
import serial

# Flask application setup
app = Flask(__name__)

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

# In-memory data store
data_store = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]

# Serial port instance
serial_connection = None

# Function to initialize the serial connection
def initialize_serial():
    """Initializes the serial connection to the instrument."""
    global serial_connection
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=SERIAL_TIMEOUT)
        print(f"Serial connection established on {SERIAL_PORT}")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return False
    return True

# Function to close the serial connection
def close_serial():
    """Closes the serial connection if it's open."""
    global serial_connection
    if serial_connection and serial_connection.is_open:
        serial_connection.close()
        print("Serial connection closed.")

# Function to send a command to the serial instrument and read the response
def send_serial_command(command):
    """Sends a command to the serial instrument and returns the response."""
    global serial_connection
    if not serial_connection:
        print("Serial connection not initialized.")
        return None
    try:
        serial_connection.write(f'{command}\n'.encode())
        response = serial_connection.readline().decode('ascii', errors='replace').strip()
        return response
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

# Function to get the instrument's version
def get_instrument_version():
    """Gets the instrument's version information."""
    response = send_serial_command('*IDN?\n')
    if response:
        return response
    return "Instrument version unavailable"

# Route for the /version endpoint
@app.route('/version', methods=['GET'])
def version():
    """Returns the instrument's version information."""
    version_info = get_instrument_version()
    return Response(version_info, mimetype='text/html')

# Function to get the entire data store
def get_data():
    """Returns the entire data store as a JSON response."""
    return jsonify(data_store)

# Route for the /getdata endpoint
@app.route('/getdata', methods=['GET'])
def get_all_data():
    """Returns the entire data store as a JSON response."""
    return get_data()

# Function to get a specific item from the data store
def get_item(item_id):
    """Gets a specific item from the data store by ID."""
    item = next((item for item in data_store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    return abort(404)

# Route for the /getset/<int:item_id> endpoint
@app.route('/getset/<int:item_id>', methods=['GET'])
def get_one_data(item_id):
    """Gets a specific item from the data store by ID."""
    return get_item(item_id)

# Function to add a new item to the data store
def add_item(name, done=False):
    """Adds a new item to the data store with the given name and default done status."""
    new_id = data_store[-1]['id'] + 1 if data_store else 1
    new_item = {"id": new_id, "name": name, "done": done}
    data_store.append(new_item)
    return jsonify(data_store)

# Route for the /getpost/<int:item_id>/<name> endpoint
@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post_data(item_id, name):
    """Appends a new item to the data store with the given name and default done status."""
    return add_item(name)

# Function to update an item in the data store
def update_item(item_id, name, done):
    """Updates an item in the data store by ID and name."""
    item = next((item for item in data_store if item['id'] == item_id), None)
    if item:
        item['name'] = name
        item['done'] = done
        return jsonify(data_store)
    return abort(404)

# Route for the /postjson endpoint
@app.route('/postjson', methods=['POST'])
def post_json_data():
    """Handles POST requests with JSON or form-encoded data."""
    if 'application/json' in request.headers.get('Content-Type', ''):
        try:
            new_item = request.get_json()
            new_id = data_store[-1]['id'] + 1 if data_store else 1
            new_item['id'] = new_id
            data_store.append(new_item)
            return jsonify(data_store)
        except json.JSONDecodeError:
            return Response("Invalid JSON data", status=400, mimetype='text/plain')
    elif 'application/x-www-form-urlencoded' in request.headers.get('Content-Type', ''):
        name = request.form.get('name', '')
        done = request.form.get('done', 'False').lower() == 'true'
        return add_item(name, done)
    else:
        return Response("Unsupported content type", status=400, mimetype='text/plain')

# Route for the /postjson endpoint
@app.route('/postjson', methods=['GET'])
def get_json_data():
    """Returns the entire data store as a JSON response."""
    return get_data()

# Main entry point
if __name__ == '__main__':
    # Initialize the serial connection
    if initialize_serial():
        try:
            # Start the Flask application
            app.run(host='0.0.0.0', debug=True)
        finally:
            # Ensure the serial port is closed on exit
            close_serial()

