        return Response("Unsupported content type", status=400, mimetype='text/plain')

# Route for the /postjson endpoint
@app.route('/postjson', methods=['GET'])
def get_json_data():
    """Returns the entire data store as a JSON response."""
    return get_data()

# Main entry point
if __name__ == '__main__':
    # Initialize the serial connection
    if initialize_serial():
        try:
            # Start the Flask application
            app.run(host='0.0.0.0', debug=True)
        finally:
            # Ensure the serial port is closed on exit
            close_serial()
